CustomField.formula:
TEXT(
    TIMEVALUE(
        Appointment_Date_Time__c -
        IF(
            OR(
                /* Check if today falls within DST period */
                AND(
                    TODAY() >= DATE(YEAR(TODAY()), 10, 1) +
                        (7 - MOD(DATE(YEAR(TODAY()), 10, 1) - DATE(1900, 1, 7), 7)),
                    TODAY() < DATE(YEAR(TODAY()), 4, 1) +
                        (7 - MOD(DATE(YEAR(TODAY()), 4, 1) - DATE(1900, 1, 7), 7))
                )
            ),
            12 / 24,  /* Subtract 12 hours during DST from GMT */
            13 / 24   /* Subtract 13 hours outside DST from GMT */
        )
    )
)
